import { Component, createMemo, onMount, Show } from "solid-js";

import { defineLegacyComponent } from "#core/ui-next/components/fxs-solid-component.js";
import { Tab } from "#core/ui-next/components/tab.jsx";
import { useAudio } from "#core/ui-next/services/audio-support.js";
import { ComponentRegistry } from "#core/ui-next/services/component-registry.js";
import { useLocalPlayerId } from "#core/ui-next/utilities/game-core-utilities.js";

import { ScreenFrame } from "#base/ui-next/components/screen-frame.jsx";
import { EmpireResourceContainer } from "#base/ui-next/screens/commerce/commerce-screen-empire-tab.jsx";
import {
	CommerceScreenContext,
	createCommerceScreenModel,
} from "#base/ui-next/screens/commerce/commerce-screen-model.js";
import { CommerceResourcesContainer } from "#base/ui-next/screens/commerce/commerce-screen-resources-tab.jsx";
import { TradeRoutesContainer } from "#base/ui-next/screens/commerce/commerce-screen-trade-tab.jsx";
import { TreasureResourceContainer } from "#base/ui-next/screens/commerce/commerce-screen-treasure-tab.jsx";

import style from "./commerce-screen.scss?url";

export interface CommerceScreenProps {
	ref?: HTMLDivElement | ((el: HTMLDivElement) => void);
}

//#region SCREEN LAYOUT
const CommerceScreenComponent: Component<CommerceScreenProps> = (_props) => {
	const model = createCommerceScreenModel();
	const audioTrigger = useAudio("CommerceScreenPopup");
	const localPlayerId = useLocalPlayerId();

	const civName = createMemo(() => {
		const player = Players.get(localPlayerId());
		if (!player) {
			return "";
		}
		const civDefinition = GameInfo.Civilizations.lookup(player.civilizationType);
		if (!civDefinition) {
			return "";
		}
		return Locale.compose(civDefinition.Name);
	});

	onMount(() => {
		audioTrigger("popup-open");
	});

	const handleOnClosing = () => {
		audioTrigger("popup-close");
	};

	const title = createMemo(() => {
		return Locale.compose("LOC_COMMERCE_SCREEN_TITLE", civName());
	});

	function onContextChanged(activatedElement: Element, _deactivatedElement: Element): void {
		// If the context has changed back to this screen from something else, ensure that InputContext.Shell is the active context (unexpected popups can change this without changing it back when closing)
		if (activatedElement.nodeName.toLocaleLowerCase() === "screen-resource-allocation") {
			Input.setActiveContext(InputContext.Shell);
		}
	}

	return (
		<CommerceScreenContext.Provider value={model}>
			<ScreenFrame
				name="Commerce-Screen"
				panelContext="screen-resource-allocation"
				audioContext="CommerceScreen"
				ornatePanelData={model.data.ornatePanelData}
				title={title()}
				onClosing={handleOnClosing}
				onContextChanged={onContextChanged}
			>
				<Tab
					class="w-full flex flex-col flex-auto pointer-events-auto relative"
					onTabChanged={model.onTabChanged}
				>
					<Tab.TabList
						class="w-187 self-center text-base font-base"
						nextHotkey="nav-next"
						previousHotkey="nav-previous"
					/>
					<Tab.Output />
					<Tab.Item
						name="Resources"
						title={() => "LOC_UI_RESOURCE_ALLOCATION_TITLE"}
						body={() => <CommerceResourcesContainer {...model.data.resourceTabData} />}
					/>
					<Tab.Item
						name="Trade"
						title={() => "LOC_COMMERCE_TRADE_ROUTE_TAB"}
						body={() => <TradeRoutesContainer {...model.data.tradeRouteTabData} />}
					/>
					<Tab.Item
						name="Empire"
						title={() => "LOC_RESOURCECLASS_EMPIRE_NAME"}
						body={() => <EmpireResourceContainer {...model.data.empireTabData} />}
					/>
					<Show when={Game.age == Database.makeHash("AGE_EXPLORATION")}>
						<Tab.Item
							name="Treasure"
							title={() => "LOC_RESOURCECLASS_TREASURE_NAME"}
							body={() => <TreasureResourceContainer {...model.data.treasureTabData} />}
						/>
					</Show>
				</Tab>
			</ScreenFrame>
		</CommerceScreenContext.Provider>
	);
};
//#endregion

export const CommerceScreen = ComponentRegistry.register({
	name: "CommerceScreen",
	styles: [style],
	createInstance: CommerceScreenComponent,
});

defineLegacyComponent("screen-resource-allocation", { classNames: ["fullscreen"] }, () => {
	Input.setActiveContext(InputContext.Shell);
	return <CommerceScreen />;
});
